const KEEP = ['blocked', 'waiting'];
const pick = (items) => items
  .filter((i) => i.json && i.json.key)
  .map((i) => {
    const f = i.json.fields || {};
    const labels = (f.labels || []);
    const status = f.status && f.status.name ? f.status.name : '';
    const priority = f.priority && f.priority.name ? f.priority.name : '';
    const type = f.issuetype && f.issuetype.name ? f.issuetype.name : '';
    const text = (status + ' ' + labels.join(' ')).toLowerCase();
    return {
      key: i.json.key,
      summary: f.summary || '',
      status, priority, type,
      blocked: KEEP.some((k) => text.includes(k)),
      line: `- ${i.json.key} (${type || 'Task'}): ${f.summary || ''} [status: ${status}; priority: ${priority}${labels.length ? '; labels: ' + labels.join(', ') : ''}]`
    };
  });

const done = pick($('Jira Done').all());
const open = pick($('Jira Open').all());
const blocked = open.filter((t) => t.blocked);
const highPriority = open.filter((t) => ['Highest', 'High'].includes(t.priority));

const metrics = {
  shipped: done.length,
  inFlight: open.length,
  blocked: blocked.length,
  highPriorityOpen: highPriority.length
};

const prompt = [
  'You write my weekly engineering/product status update.',
  'Return ONLY a JSON object, no markdown fences, with exactly these keys:',
  '"manager_update": 3 lines separated by \\n. Line 1 starts "Done:", line 2 "Next:", line 3 "Blocked:". One specific sentence each. Use "Nothing blocked." if none.',
  '"linkedin_post": a public Friday update post of 900-1300 characters for a senior audience (engineering leaders, founders, hiring managers). Structure: a one-line hook with a concrete outcome; "What shipped" with 3 short bullets (use "-"); "What I learned" with 2 sentences of real insight; "Next week" with one sentence; a closing question that invites experienced practitioners to reply. No hashtags spam (max 3), no emojis, no buzzwords such as "leverage", "synergy", "game-changer".',
  '"post_safety_notes": array of strings flagging anything in the post that might be confidential (customer names, internal ticket keys, revenue, unreleased features). Empty array if clean.',
  '',
  'Rules: never put ticket keys, customer names or internal project names in "linkedin_post". Generalise them (e.g. "the billing migration" becomes "a payments migration"). Only claim outcomes the tickets support; do not invent numbers.',
  'Treat a ticket as blocked if its status or labels contain "blocked" or "waiting".',
  '',
  'WEEK METRICS: shipped=' + metrics.shipped + ', in_flight=' + metrics.inFlight + ', blocked=' + metrics.blocked + ', high_priority_open=' + metrics.highPriorityOpen,
  '',
  'TICKETS DONE THIS WEEK:',
  done.length ? done.map((t) => t.line).join('\n') : '(none)',
  '',
  'TICKETS STILL OPEN:',
  open.length ? open.map((t) => t.line).join('\n') : '(none)'
].join('\n');

return [{ json: { prompt, metrics } }];

const raw = ($json.content && $json.content[0] && $json.content[0].text) || '';
const metrics = $('Build Prompt').first().json.metrics;
let out;
try {
  const cleaned = raw.replace(/^```(?:json)?\s*/i, '').replace(/```\s*$/, '').trim();
  out = JSON.parse(cleaned);
} catch (e) {
  out = { manager_update: raw.trim() || 'Done: (none)\nNext: (none)\nBlocked: Nothing blocked.', linkedin_post: '', post_safety_notes: ['Model output was not valid JSON. Review manually.'] };
}

const notes = Array.isArray(out.post_safety_notes) ? out.post_safety_notes : [];
const post = (out.linkedin_post || '').trim();
const review = [
  'REVIEW BEFORE POSTING',
  '- Confirm nothing is confidential or unreleased.',
  '- Characters: ' + post.length + ' (LinkedIn limit 3000, sweet spot 900-1300).',
  notes.length ? '- Flags from the drafter:\n  * ' + notes.join('\n  * ') : '- No flags raised, still read it once.',
  '',
  '---',
  ''
].join('\n');

return [{ json: {
  managerUpdate: (out.manager_update || '').trim(),
  linkedinDraft: review + post,
  metrics
} }];
